using TechStore.App.Controllers;namespace TechStore.App.Views; public partial class CrudForm:Form{readonly string module;readonly AppController controller=new();public CrudForm(string module){this.module=module;InitializeComponent();Text=module;Shown+=async(_,_)=>await LoadData();}async Task LoadData(){grid.DataSource=module=="Productos"?await controller.ProductsAsync(search.Text):await controller.EntitiesAsync(module,search.Text);}async void Refresh_Click(object? s,EventArgs e)=>await LoadData();void Action_Click(object? s,EventArgs e)=>MessageBox.Show("La operación se realiza mediante edición validada y baja lógica. Seleccione un registro.",module);}
